//! C++ `hg::LuaScripting::initLevelControl` (LuaScripting.cpp:509-956):
//! the 43 `LevelStatus` accessor pairs + 6 `HexagonGameStatus` accessor
//! pairs (all generated by the C++ `makeLuaAccessor` helper) plus the 6
//! direct `l_*` registrations that follow them.

use super::{lock, GameApiState, State};
use crate::context::LuaContext;
use crate::error::LuaError;
use crate::metadata::FnMeta;

/// Registers `l_get<Name>` / `l_set<Name>` over the state field path
/// `target` — the Rust form of the C++ `makeLuaAccessor` lambda pair
/// (mapping §1.5.2/§1.5.4). The call site passes the field as a getter
/// and setter closure over `&mut GameApiState`; the macro handles the
/// `State` cloning and locking.
macro_rules! reg_accessor {
    (
        $ctx:expr, $st:expr, $Name:literal, $Ty:ty, $ret:literal,
        $get:expr, $set:expr, $getter:expr, $setter:expr
        ) => {{
        // The `st` clone is hoisted out of the closure argument so the
        // closure itself is the 4th macro argument (`add_lua_fn!` matches on
        // the closure tokens).
        let st = { $st.clone() };
        $crate::add_lua_fn!(
            $ctx,
            concat!("l_get", $Name),
            crate::metadata::FnMeta {
                ret: $ret,
                arg_types: &[],
            },
            move || $get(&mut lock(&st)),
        )?
        .doc($getter);

        let st = { $st.clone() };
        $crate::add_lua_fn!(
            $ctx,
            concat!("l_set", $Name),
            crate::metadata::FnMeta {
                ret: "void",
                arg_types: &[$ret],
            },
            move |value: $Ty| {
                $set(&mut lock(&st), value);
            },
        )?
        .arg("value")
        .doc($setter);
    }};
}

